typedef struct Node {
    int val;
    struct Node *next;
} Node;

// Delete function using pointer-to-pointer (indirect pointer)
// Allows uniform deletion of head, middle, or tail.
void list_delete_key(Node **head, int key) {
    Node **pp = head; // Pointer to the 'next' field pointer
    while (*pp) {
        if ((*pp)->val == key) {
            Node *tmp = *pp;
            *pp = tmp->next; // Pointer aliasing/re-linking
            free(tmp);
            return;
        }
        pp = &(*pp)->next; // Advance pp to point to the next node's 'next' field
    }
}
