#define offsetof(T, M) ((size_t)&(((T*)0)->M))
#define container_of(ptr, type, member) \
    (type *)((char *)(ptr) - offsetof(type, member))

// Memory aliasing: Recovering base structure from internal field pointer
struct ListItem { struct ListItem *next; };

struct DataBlock {
    int id;
    int payload[10];
    struct ListItem node; // Field used for linking
};

void process_node(struct ListItem *ln) {
    // Calculate the address of the parent struct DataBlock
    struct DataBlock *parent = container_of(ln, struct DataBlock, node);
    parent->id = 42; // Modify data through the recovered pointer
}
